package com.martorell.albert.basketcoach.domain.model

/**
 * Analytical finding generated by AI analysis of past matches.
 *
 * Highlights specific strengths, vulnerabilities, or tactical trends across Phase 1 games.
 *
 * @property id Unique identifier for the insight.
 * @property title Concise headline summarizing the finding.
 * @property description Detailed tactical assessment and supporting observations.
 * @property category Domain category classifying the insight ([InsightCategory]).
 * @property relatedGameRounds List of competition round numbers that exhibit or evidence this pattern.
 */
data class Insight(
    val id: String,
    val title: String,
    val description: String,
    val category: InsightCategory,
    val relatedGameRounds: List<Int> = emptyList()
)
